with employees_by_department as (select dept_id, sum(case when level = 'L1' then salary else 0 end) l1_salary, sort_array(collect_set(level)) level_list from employees where is_remote = true group by dept_id) select d.budget, d.dept_name, ebd.l1_salary, ebd.level_list from departments d left outer join employees_by_department ebd on d.id = ebd.dept_id where ebd.l1_salary > 63 order by ebd.l1_salary, dept_name
